  "dDurationMs": 1935,
  "segs": [ {
    "utf8": "有時候可能變做在戲劇裡面 "
  } ]
}, {
  "tStartMs": 1476141,
  "dDurationMs": 967,
  "segs": [ {
    "utf8": "書本裡面"
  } ]
}, {
  "tStartMs": 1477108,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "但有些它就是在空間裡"
  } ]
}, {
  "tStartMs": 1478810,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "那這個空間就應該被保留"
  } ]
}, {
  "tStartMs": 1480412,
  "dDurationMs": 1151,
  "segs": [ {
    "utf8": "我認為那個空間就是 "
  } ]
}, {
  "tStartMs": 1481563,
  "dDurationMs": 1184,
  "segs": [ {
    "utf8": "剛剛講的基礎設施"
  } ]
}, {
  "tStartMs": 1482747,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "你剛剛講到說戲劇 "
  } ]
}, {
  "tStartMs": 1484149,
  "dDurationMs": 2269,
  "segs": [ {
    "utf8": "跟這個小說漫畫也好"
  } ]
}, {
  "tStartMs": 1486418,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "這個我剛剛突然閃過一個念頭"
  } ]
}, {
  "tStartMs": 1488420,
  "dDurationMs": 2185,
  "segs": [ {
    "utf8": "但我覺得這一點也是蠻重要的"
  } ]
}, {
  "tStartMs": 1490605,
  "dDurationMs": 1969,
  "segs": [ {
    "utf8": "其實我們應該要去鼓勵大家"
  } ]
}, {
  "tStartMs": 1492574,
  "dDurationMs": 1034,
  "segs": [ {
    "utf8": " 做這個創作"
  } ]
}, {
  "tStartMs": 1493608,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "因為日本我們知道說 "
  } ]
}, {
  "tStartMs": 1494809,
  "dDurationMs": 1202,
  "segs": [ {
    "utf8": "它不但有大河劇"
  } ]
}, {
  "tStartMs": 1496011,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "對 還有晨間劇"
  } ]
}, {
  "tStartMs": 1497412,
  "dDurationMs": 3003,
  "segs": [ {
    "utf8": "大河劇處理的可能是比較古代的歷史"
  } ]
}, {
  "tStartMs": 1500415,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "但晨間劇處理的就是比較近代的"
  } ]
}, {
  "tStartMs": 1502617,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "也是每年 每年"
  } ]
}, {
  "tStartMs": 1504219,
  "dDurationMs": 3287,
  "segs": [ {
    "utf8": "然後帶動不同的一些產業"
  } ]
}, {
  "tStartMs": 1507506,
  "dDurationMs": 1117,
  "segs": [ {
    "utf8": "跟地區的發展"
  } ]
}, {
  "tStartMs": 1508623,
  "dDurationMs": 1385,
  "segs": [ {
    "utf8": "那台北雖然說"
  } ]
}, {
  "tStartMs": 1510008,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "我們剛剛有提到說"
  } ]
}, {
  "tStartMs": 1511009,
  "dDurationMs": 1585,
  "segs": [ {
    "utf8": "像天橋上的魔術師 "
  } ]
}, {
  "tStartMs": 1512594,
  "dDurationMs": 1818,
  "segs": [ {
    "utf8": "或者是以前的一些"
  } ]
}, {
  "tStartMs": 1514412,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "可能在台北的著作"
  } ]
}, {
  "tStartMs": 1516214,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "但是我覺得還是缺少了一點"
  } ]
}, {
  "tStartMs": 1518416,
  "dDurationMs": 2403,
  "segs": [ {
    "utf8": "大家一起來寫台北的故事"
  } ]
}, {
  "tStartMs": 1520819,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "這真的很需要"
  } ]
}, {
  "tStartMs": 1521920,
  "dDurationMs": 3186,
  "segs": [ {
    "utf8": "然後故事 戲劇 小說 電玩"
  } ]
}, {
  "tStartMs": 1525106,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "剛剛看到 《超人力霸王》"
  } ]
}, {
  "tStartMs": 1526508,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "我比較喜歡假面騎士"
  } ]
}, {
  "tStartMs": 1528710,
  "dDurationMs": 2503,
  "segs": [ {
    "utf8": "假面騎士也是每年都有"
  } ]
}, {
  "tStartMs": 1531213,
  "dDurationMs": 2802,
  "segs": [ {
    "utf8": "它每年 它可能有跟一些地區做結合"
  } ]
}, {
  "tStartMs": 1534015,
  "dDurationMs": 2503,
  "segs": [ {
    "utf8": "它可能跟當時的議題做結合"
  } ]
}, {
  "tStartMs": 1536518,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "當時新的科技做結合"
  } ]
}, {
  "tStartMs": 1538720,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "我覺得那個其實都是很重要的事情"
  } ]
}, {
  "tStartMs": 1540622,
  "dDurationMs": 1051,
  "segs": [ {
    "utf8": "你講到假面騎士 "
  } ]
}, {
  "tStartMs": 1541673,
  "dDurationMs": 1235,
  "segs": [ {
    "utf8": "我今天是沒有帶來"
  } ]
}, {
  "tStartMs": 1542908,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "我去年還特別去了"
  } ]
}, {
  "tStartMs": 1544409,
  "dDurationMs": 1819,
  "segs": [ {
    "utf8": "石之森章太郎的家 "
  } ]
}, {
  "tStartMs": 1546228,
  "dDurationMs": 1685,
  "segs": [ {
    "utf8": "去朝聖這樣子"
  } ]
}, {
  "tStartMs": 1547913,
  "dDurationMs": 1801,
  "segs": [ {
    "utf8": "我一講阿宅的話題可能講不完"
  } ]
}, {
  "tStartMs": 1549714,
  "dDurationMs": 701,
  "segs": [ {
    "utf8": "我真的超愛"
  } ]
}, {
  "tStartMs": 1550415,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "我那天看到有人帶了一個那個變身"
  } ]
}, {
  "tStartMs": 1552517,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "他知道我喜歡Kabuto"
  } ]
}, {
  "tStartMs": 1553518,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "Kabuto是平成年代"
  } ]
}, {
  "tStartMs": 1554920,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "對 帶了那個"
  } ]
}, {
  "tStartMs": 1556121,
  "dDurationMs": 3220,
  "segs": [ {
    "utf8": "那個我就這樣放上去就 變身"
  } ]
}, {
  "tStartMs": 1560809,
  "dDurationMs": 1134,
  "segs": [ {
    "utf8": "變身這個梗 "
  } ]
}, {
  "tStartMs": 1561943,
  "dDurationMs": 1969,
  "segs": [ {
    "utf8": "應該說變身這個動作"
  } ]
}, {
  "tStartMs": 1563912,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "從我們童年就開始"
  } ]
}, {
  "tStartMs": 1565413,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "好 現在就講到一個"
  } ]
